    @Override public void onCreate(Bundle saved){super.onCreate(saved);state=(State)getLastNonConfigurationInstance();boolean fresh=state==null;if(fresh)state=new State(getApplicationContext());state.owner=new WeakReference<>(this);show();if(fresh){if(saved!=null)state.resumeNotice="上次编辑已中断，未保存的调整需重新设置，外部照片请重新选择。";load(getIntent().getStringExtra("roll"));}else{refresh();if(state.preview==null&&!state.loading)changed(false);}}
