        ScrollView scroll=new ScrollView(this);scroll.setFillViewport(false);LinearLayout body=column();body.setPadding(dp(16),0,dp(16),dp(16));scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
        info=text("",12);info.setTextColor(getColor(R.color.ui_muted));body.addView(info);space(body,12);
        preview=new ImageView(this){@Override protected void onMeasure(int w,int h){int width=MeasureSpec.getSize(w);int cap=Math.round(getResources().getDisplayMetrics().heightPixels*.40f/Math.max(1f,getResources().getConfiguration().fontScale/1.15f));super.onMeasure(w,MeasureSpec.makeMeasureSpec(Math.min(Math.round(width*1.25f),Math.max(dp(170),cap)),MeasureSpec.EXACTLY));}};
        preview.setTag("poster-preview");preview.setScaleType(ImageView.ScaleType.FIT_CENTER);preview.setBackgroundColor(Color.TRANSPARENT);preview.setContentDescription("分享图预览，照片与输出使用相同排版");body.addView(preview,new LinearLayout.LayoutParams(-1,-2));space(body,8);
