        LinearLayout options=new LinearLayout(this);for(String label:new String[]{"照片","排版","文字"}){Button b=action(label,false,()->{if(locked())return;if(label.equals("照片"))photos();else if(label.equals("排版"))layoutOptions();else words();});LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,-2,1);if(options.getChildCount()>0)lp.leftMargin=dp(8);options.addView(b,lp);editing.add(b);}body.addView(options);space(body,12);
