        LinearLayout footer=column();footer.setPadding(dp(16),dp(8),dp(16),dp(12));save=action("保存图片",false,()->save(false));share=action("保存并分享",true,()->save(true));footer.addView(save,new LinearLayout.LayoutParams(-1,-2));space(footer,8);footer.addView(share,new LinearLayout.LayoutParams(-1,-2));root.addView(footer);refresh();
